/** A launch URL must remain within the same Runhive origin and gateway. */
export function validateLaunch(data, origin) {
  const adminId = Number(data?.admin_id)
  if (!Number.isSafeInteger(adminId) || adminId <= 0 || typeof data?.ticket !== 'string' || !data.ticket || data.ticket.length > 2048) {
    throw new Error('账号验证信息不完整，请重新连接。')
  }
  const url = new URL(data?.launch_url || '', origin)
  if (url.origin !== origin || url.pathname !== '/llm-center/' || url.username || url.password || url.search || url.hash) {
    throw new Error('大模型中心启动地址无效，请联系管理员。')
  }
  url.hash = new URLSearchParams({ ticket: data.ticket, admin_id: String(adminId) }).toString()
  return { url: url.toString(), adminId }
}

export function isGatewayMessage(event, frameWindow, origin, adminId) {
  return Boolean(frameWindow && event.source === frameWindow && event.origin === origin
    && event.data && typeof event.data === 'object'
    && event.data.source === 'llm-center-auth-gate'
    && Number(event.data.admin_id) === adminId)
}

/** User-facing errors are Chinese; technical diagnostics stay in service logs. */
export function chineseError(error, fallback = '大模型中心暂时无法打开，请稍后重新连接。') {
  const message = String(error?.message || '')
  return /[\u3400-\u9fff]/u.test(message) && message.length <= 200 ? message : fallback
}
